class Solution {
public:
    int countSubsequences(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        long long ans = 0;
        auto c2 = [](long long x) { return x * (x - 1) / 2; };
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            map<int,long long> L, R;
            for (int j = 0; j < i; j++) L[nums[j]]++;
            for (int j = i+1; j < n; j++) R[nums[j]]++;
            long long Lv = 0, Rv = 0;
            if (L.count(v)) { Lv = L[v]; L.erase(v); }
            if (R.count(v)) { Rv = R[v]; R.erase(v); }
            long long A = 0, B = 0;
            for (auto& kv : L) A += kv.second;
            for (auto& kv : R) B += kv.second;
            long long p[3][3] = {{0}};
            p[0][0] = 1;
            set<int> ks;
            for (auto& kv : L) ks.insert(kv.first);
            for (auto& kv : R) ks.insert(kv.first);
            for (int k : ks) {
                long long lx = L.count(k) ? L[k] : 0;
                long long rx = R.count(k) ? R[k] : 0;
                long long q[3][3] = {{0}};
                for (int a = 0; a < 3; a++)
                    for (int b = 0; b < 3; b++) {
                        long long c = p[a][b];
                        if (!c) continue;
                        q[a][b] += c;
                        if (a < 2) q[a+1][b] += c * lx;
                        if (b < 2) q[a][b+1] += c * rx;
                    }
                memcpy(p, q, sizeof(p));
            }
            long long t = Lv * p[1][2] + Rv * p[2][1]
                + c2(Lv) * c2(Rv)
                + c2(Lv) * Rv * B + Lv * c2(Rv) * A
                + c2(Lv) * c2(B) + c2(A) * c2(Rv) + Lv * Rv * A * B;
            ans = (ans + t) % MOD;
        }
        return (int)ans;
    }
};

