class Solution {
    public int countSubsequences(int[] nums) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            Map<Integer, Long> L = new HashMap<>(), R = new HashMap<>();
            for (int j = 0; j < i; j++) L.merge(nums[j], 1L, Long::sum);
            for (int j = i+1; j < n; j++) R.merge(nums[j], 1L, Long::sum);
            long Lv = L.getOrDefault(v, 0L); L.remove(v);
            long Rv = R.getOrDefault(v, 0L); R.remove(v);
            long A = 0, B = 0;
            for (long x : L.values()) A += x;
            for (long x : R.values()) B += x;
            long[][] p = new long[3][3];
            p[0][0] = 1;
            Set<Integer> ks = new TreeSet<>();
            ks.addAll(L.keySet()); ks.addAll(R.keySet());
            for (int k : ks) {
                long lx = L.getOrDefault(k, 0L), rx = R.getOrDefault(k, 0L);
                long[][] q = new long[3][3];
                for (int a = 0; a < 3; a++)
                    for (int b = 0; b < 3; b++) {
                        long c = p[a][b];
                        if (c == 0) continue;
                        q[a][b] += c;
                        if (a < 2) q[a+1][b] += c * lx;
                        if (b < 2) q[a][b+1] += c * rx;
                    }
                p = q;
            }
            long t = Lv * p[1][2] + Rv * p[2][1]
                + c2(Lv) * c2(Rv)
                + c2(Lv) * Rv * B + Lv * c2(Rv) * A
                + c2(Lv) * c2(B) + c2(A) * c2(Rv) + Lv * Rv * A * B;
            ans = (ans + t) % MOD;
        }
        return (int)ans;
    }
    private long c2(long x) { return x * (x - 1) / 2; }
}

